```python
def busca(xs, alvo):
    lo, hi = 0, len(xs) - 1
    while lo < hi:
        meio = (lo + hi) // 2
        if xs[meio] == alvo:
            return meio
        if xs[meio] < alvo:
            lo = meio + 1
        else:
            hi = meio - 1
    return -1
